package com.bank.exceptiontable;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class ExceptionTableTest {

    // Simulates method with try-catch
    String process(String input) {
        try {
            if ("io".equals(input)) throw new java.io.IOException("IO fail");
            if ("sql".equals(input)) throw new java.sql.SQLException("SQL fail");
            return "SUCCESS: " + input;
        } catch (java.io.IOException e) {
            return "CAUGHT_IO: " + e.getMessage();
        } catch (java.sql.SQLException e) {
            return "CAUGHT_SQL: " + e.getMessage();
        }
    }

    @Test
    void happyPath_zeroCost() {
        // No exception → try body runs as plain bytecode → zero overhead!
        assertThat(process("TRD-001")).isEqualTo("SUCCESS: TRD-001");
    }

    @Test
    void ioException_matchesFirstHandler() {
        // IOException thrown → exception table: matches entry 1 → handler PC 13
        assertThat(process("io")).isEqualTo("CAUGHT_IO: IO fail");
    }

    @Test
    void sqlException_matchesSecondHandler() {
        // SQLException thrown → exception table: skips entry 1, matches entry 2
        assertThat(process("sql")).isEqualTo("CAUGHT_SQL: SQL fail");
    }

    @Test
    void tryCatchPerformance_zeroCostWhenNoThrow() {
        int iterations = 1_000_000;

        // WITH try-catch (no exception thrown):
        long withTry = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            process("TRD-001");  // happy path inside try
        }
        long withTryTime = (System.nanoTime() - withTry) / 1_000_000;

        // WITHOUT try-catch:
        long withoutTry = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            "SUCCESS: TRD-001".length();  // plain code, no try
        }
        long withoutTryTime = (System.nanoTime() - withoutTry) / 1_000_000;

        System.out.println("With try: " + withTryTime + "ms, Without: " + withoutTryTime + "ms");
        // Nearly identical! try-catch on happy path ≈ zero cost.
    }
}
